import Foundation

/// Registrable domains ("sites") from Mozilla's Public Suffix List, ICANN and private sections,
/// with wildcard (`*.ck`) and exception (`!www.ck`) rules, following the algorithm published at
/// https://github.com/publicsuffix/list/wiki/Format. Hosts are compared in ASCII (punycode) form,
/// as URL hosts are; the embedded data is generated by `scripts/generate-public-suffix-swift.py`.
public struct BrowserPublicSuffixList: Sendable {
    private let rules: Set<String>
    /// `*.ck` is stored as `ck`.
    private let wildcards: Set<String>
    /// `!www.ck` is stored as `www.ck`.
    private let exceptions: Set<String>

    /// The list embedded in this build.
    public static let shared = BrowserPublicSuffixList(rules: embeddedRules)

    /// Parses one rule per line, in the data file's syntax without comments.
    public init(rules text: String) {
        var rules = Set<String>()
        var wildcards = Set<String>()
        var exceptions = Set<String>()
        for line in text.split(whereSeparator: \.isNewline) {
            let rule = line.trimmingCharacters(in: .whitespaces).lowercased()
            guard !rule.isEmpty, !rule.hasPrefix("//") else { continue }
            if rule.hasPrefix("!") {
                exceptions.insert(String(rule.dropFirst()))
            } else if rule.hasPrefix("*.") {
                wildcards.insert(String(rule.dropFirst(2)))
            } else {
                rules.insert(rule)
            }
        }
        self.rules = rules
        self.wildcards = wildcards
        self.exceptions = exceptions
    }

    /// The number of trailing labels forming the public suffix of `labels`.
    private func publicSuffixLength(of labels: [Substring]) -> Int {
        let count = labels.count
        func name(from index: Int) -> String { labels[index...].joined(separator: ".") }
        // Exception rules prevail over every other rule: the suffix is the rule minus its first label.
        for index in 0..<count where exceptions.contains(name(from: index)) {
            return count - index - 1
        }
        // Otherwise the matching rule with the most labels; the implicit default rule is "*".
        var length = 1
        for index in 0..<count {
            let labelCount = count - index
            if labelCount > length, rules.contains(name(from: index)) { length = labelCount }
            if labelCount > length, index + 1 < count, wildcards.contains(name(from: index + 1)) { length = labelCount }
        }
        return length
    }

    /// The registrable domain of `host` (`www.example.co.uk` → `example.co.uk`,
    /// `alice.github.io` → `alice.github.io`), or nil when the host is itself a public suffix,
    /// is empty, has an empty label, or is an IP address.
    public func registrableDomain(of host: String) -> String? {
        var host = host.lowercased()
        if host.hasSuffix(".") { host.removeLast() }
        guard !host.isEmpty, !host.hasPrefix("."), !Self.isIPAddress(host) else { return nil }
        let labels = host.split(separator: ".", omittingEmptySubsequences: false)
        guard !labels.contains(where: \.isEmpty) else { return nil }
        let suffixLength = publicSuffixLength(of: labels)
        guard labels.count > suffixLength else { return nil }
        return labels.suffix(suffixLength + 1).joined(separator: ".")
    }

    /// The site used to compare two addresses: the registrable domain, or the whole host for IP
    /// addresses, single-label hosts and hosts that are public suffixes themselves.
    public func site(of url: URL) -> String? {
        guard var host = url.host?.lowercased(), !host.isEmpty else { return nil }
        if host.hasSuffix(".") { host.removeLast() }
        return registrableDomain(of: host) ?? host
    }

    private static func isIPAddress(_ host: String) -> Bool {
        if host.contains(":") { return true }
        let parts = host.split(separator: ".", omittingEmptySubsequences: false)
        return parts.count == 4 && parts.allSatisfy { !$0.isEmpty && $0.allSatisfy(\.isNumber) }
    }
}
